from collections import deque, defaultdict
R,C=grid.shape
seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  col=int(grid[r,c])
  if col not in (0,2) and (r,c) not in seen:
   q=[(r,c)]; seen.add((r,c)); pts=[]
   while q:
    p=q.pop(); pts.append(p)
    for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
     z=(p[0]+dr,p[1]+dc)
     if 0<=z[0]<R and 0<=z[1]<C and z not in seen and grid[z]==col:
      seen.add(z);q.append(z)
   comps.append((col, sorted(pts)))
for i,(col,pts) in enumerate(comps):
 print(i,col, len(pts), 'bbox', (min(r for r,c in pts),max(r for r,c in pts),min(c for r,c in pts),max(c for r,c in pts)), pts)
print('marker2:', [tuple(x) for x in np.argwhere(grid==2)])

grid[14,18]=2; grid[14,23]=2
print('markers',len(np.argwhere(grid==2)), [tuple(map(int,p)) for p in np.argwhere(grid==2)])
# inspect shape components, and translations
piece_names=['one_big','one_small','three','eight','four','nine','five']
piece_comps={name:pts for name,(col,pts) in zip(piece_names, comps)}
translations={'one_big':(7,-7),'one_small':(8,7),'three':(-1,12),'eight':(9,-13),'four':(0,0),'nine':(-6,4),'five':(3,-7)}

marker_groups={
 'one_big':[(0,22),(1,23),(3,16),(4,21)],
 'one_small':[(1,10),(1,12)],
 'three':[(8,3),(9,4),(10,5),(10,7)],
 'eight':[(9,19),(9,22),(14,18),(14,23)],
 'four':[(10,9),(11,14),(14,8),(15,10)],
 'nine':[(20,4),(21,6),(24,2),(24,5)],
 'five':[(20,12),(20,17)],
}
out=np.zeros((26,26), dtype=int)
occupants=defaultdict(list)
for name,pts in piece_comps.items():
 dr,dc=translations[name]
 col=int(grid[pts[0]])
 for r,c in pts:
  q=(r+dr,c+dc); occupants[q].append((name,col,'color'))
 for r,c in marker_groups[name]:
  q=(r+dr,c+dc); occupants[q].append((name,2,'marker'))
for q, vals in occupants.items():
 vals_colors={v[1] for v in vals}
 if len(vals_colors)>1:
  print('CONFLICT',q,vals)
 if 2 in vals_colors: out[q]=2
 else: out[q]=next(iter(vals_colors))
print('nonzero output', int(np.count_nonzero(out)), 'unique dots',int(np.count_nonzero(out==2)))
print('bounds', [(int(a.min()),int(a.max())) for a in np.where(out!=0)])
print('\n'.join(' '.join(str(int(x)) for x in row) for row in out))
